powerpagecomponent.content:
{
  "source": "{% comment %}
sections--program-detail

Supports:
1. Program selected on Slot (hit_program)
2. Querystring id (legacy support)

Image:
- hit_imageurl
{% endcomment %}

{% assign programId = '' %}

{% comment %}
Preferred source = slot lookup
Fallback = querystring id
{% endcomment %}

{% if slot.hit_program %}
  {% assign programId = slot.hit_program.id | default: slot.hit_program | strip %}
{% endif %}

{% if programId == '' %}
  {% assign programId = request.params.id | default: '' | replace: '{','' | replace: '}','' | strip %}
{% endif %}

{% if debug %}

<div style="background:#0a2540;color:#fff;padding:10px;font-size:12px;margin-bottom:12px;">
  Program Detail Debug<br>
  slot.hit_program = {{ slot.hit_program }}<br>
  slot.hit_program.id = {{ slot.hit_program.id }}<br>
  resolved programId = {{ programId }}
</div>

{% endif %}

{% if programId == '' %}

<section class="hit-empty">
  <h2>No Program Selected</h2>
  <p>This Program Detail component has not been linked to a Program.</p>
</section>

{% else %}

{% fetchxml programQuery %}
<fetch top="1" mapping="logical">
  <entity name="hit_program">

    <attribute name="hit_programid" />
    <attribute name="hit_name" />
    <attribute name="hit_displaytitle" />
    <attribute name="hit_description" />
    <attribute name="hit_imageurl" />
    <attribute name="hit_isactive" />

    <filter>
      <condition attribute="hit_programid"
                 operator="eq"
                 value="{{ programId }}" />

      <condition attribute="hit_isactive"
                 operator="eq"
                 value="1" />
    </filter>

  </entity>
</fetch>
{% endfetchxml %}

{% assign program = programQuery.results.entities | first %}

{% if program == nil %}

<section class="hit-empty">
  <h2>Program not found</h2>
  <p>The selected Program could not be located.</p>
</section>

{% else %}

{% assign title =  program.hit_displaytitle  | default: program.hit_name  | strip %}

{% assign body =  program.hit_description  | default: '' %}

{% assign imageUrl =  program.hit_imageurl  | default: '' %}

<article class="hit-program-detail">

  {% if imageUrl != '' %}

    <div class="hit-program-detail__hero">

      <img
        class="hit-program-detail__image"
        src="{{ imageUrl | escape }}"
        alt="{{ title | escape }}"
        loading="lazy">

    </div>

  {% endif %}

  <div class="hit-program-detail__content">

    <h1 class="hit-program-detail__title">
      {{ title }}
    </h1>

    {% if body != blank %}
      <div class="hit-program-detail__body">
        {{ body }}
      </div>
    {% endif %}

  </div>

</article>

<style>

.hit-program-detail{
  max-width:1200px;
  margin:0 auto;
}

.hit-program-detail__hero{
  margin-bottom:32px;
}

.hit-program-detail__image{
  width:100%;
  display:block;
  border-radius:20px;
}

.hit-program-detail__title{
  font-size:42px;
  font-weight:800;
  line-height:1.1;
  margin-bottom:24px;
}

.hit-program-detail__body{
  line-height:1.8;
  font-size:1.05rem;
}

.hit-empty{
  max-width:1200px;
  margin:0 auto;
  padding:40px 20px;
}

</style>

{% endif %}
{% endif %}"
}
